  async function renderTaskNotice(j,event){
    let persona;
    const owner=isOwnerKey(j.key);const preset=owner?'dafeiyu':'jingjing-guest';
    persona=readConversationPersona(preset);
    const history=owner?ownerChat:j.key?loadGuestChat(j.key):[];
    persona+='\n'+temporal.context(j.key,{history});
    const recent=history.slice(-6).map(({at,dir,text})=>({at:beijingTime(at),dir,text:String(text).slice(0,900)}));
    const prompt=buildProgressPrompt({persona,recent,task:j,event,lastSent:j.sentText,now:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})});
    return validateNarration(await runMemoPrompt(prompt,20000,{purpose:'progress_narration',effort:cfg.dsh.reasoningEffort||'high',preset:owner?'jingjing-owner-chat':'jingjing-memo',contextKey:j.key}),j);
  }
