    if(recent&&Date.now()-recent.at<3000)await sleepMs(3000-(Date.now()-recent.at));
    await syncStickerLibrary(false);const exact=findSticker(stickerEntries,query);const matches=formatStickerList(stickerEntries,query,50).stickers;
    const e=exact||matches.sort((a,b)=>(a.lastUsedAt||0)-(b.lastUsedAt||0))[0];if(!e)throw Error('没找到合适的收藏表情');
